184	
185	  // model is the provider-specific model identifier.
186	  // Empty string falls back to the engine default.
187	  // OPENAI examples:
188	  //   - whisper-1 (legacy, lower cost)
189	  //   - gpt-4o-transcribe, gpt-4o-mini-transcribe (higher quality)
190	  //   - gpt-4o-transcribe-diarize (includes speaker labels)
191	  // GEMINI examples:
192	  //   - gemini-2.5-flash (default, multimodal call)
193	  //   - gemini-2.5-pro
194	  string model = 2;
195	
196	  // language is the default ISO 639-1 language hint sent to the provider.
